@MainActor
func testProductRegistrationNavigationAndBack() throws {
    let app = XCUIApplication()
    app.launch()

    // 保存済み商品の有無によらず、共通の登録操作から遷移できる。
    let productList = app.navigationBars["商品一覧"]
    XCTAssertTrue(productList.waitForExistence(timeout: 5))

    let registerButton = productList.buttons["product-list-register"]
    XCTAssertTrue(registerButton.isHittable)
    registerButton.tap()

    let registration = app.navigationBars["商品登録"]
    XCTAssertTrue(registration.waitForExistence(timeout: 5))
    XCTAssertTrue(app.staticTexts["商品登録機能は準備中です"].exists)
    XCTAssertFalse(app.buttons["保存"].exists)
    XCTAssertFalse(app.textFields.firstMatch.exists)

    // 暫定画面の標準戻るボタンで一覧と登録操作に戻れる。
    let backButton = registration.buttons.element(boundBy: 0)
    XCTAssertTrue(backButton.isHittable)
    backButton.tap()

    XCTAssertTrue(productList.waitForExistence(timeout: 5))
    XCTAssertTrue(registerButton.isHittable)
}

struct ContentView: View {
    var body: some View {
        NavigationStack {
            ProductListView()
        }
    }
}

struct ProductListView: View {
    @Query(sort: [SortDescriptor(\Product.type), SortDescriptor(\Product.name)])
    private var products: [Product]

var body: some View {
    Group {
        if products.isEmpty {
            ContentUnavailableView {
                Label("商品はまだありません", systemImage: "cabinet")
            } description: {
                Text("商品を登録すると、名前と種類をここで確認できます。")
            } actions: {
                NavigationLink("商品を登録") {
                    ProductRegistrationPlaceholderView()
                }
                .buttonStyle(.borderedProminent)
            }
        } else {
            List(products, id: \.persistentModelID) { product in
                ProductListRow(product: product)
            }
        }

.navigationTitle("商品一覧")
.toolbar {
    ToolbarItem(placement: .topBarTrailing) {
        NavigationLink {
            ProductRegistrationPlaceholderView()
        } label: {
            Label("商品を登録", systemImage: "plus")
        }
        .accessibilityIdentifier("product-list-register")
    }
}

@MainActor
func testProductRegistrationNavigationAndBack() throws {
    let app = XCUIApplication()
    app.launch()

    // 保存済み商品の有無によらず、共通の登録操作から遷移できる。
    let productList = app.navigationBars["商品一覧"]
    XCTAssertTrue(productList.waitForExistence(timeout: 5))

    let registerButton = productList.buttons["product-list-register"]
    XCTAssertTrue(registerButton.isHittable)
    registerButton.tap()

private var displayName: String {
    let name = product.name.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !name.isEmpty else {
        return "名前未設定"
    }

    return name
}

private var displayType: String {
    let type = product.type.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !type.isEmpty else {
        return "種類未設定"
    }

    return type
}

var body: some View {
    VStack(alignment: .leading, spacing: 4) {
        Text(displayName)
            .font(.headline)

        Text("種類: \(displayType)")
            .font(.subheadline)
            .foregroundStyle(.secondary)
    }
    .fixedSize(horizontal: false, vertical: true)
    .accessibilityElement(children: .ignore)
    .accessibilityLabel("商品名、\(displayName)、種類、\(displayType)")
}

init(products: [Product]) {
    do {
        let schema = Schema([Product.self, Item.self])
        let configuration = ModelConfiguration(
            schema: schema,
            isStoredInMemoryOnly: true,
            cloudKitDatabase: .none
        )
        let container = try ModelContainer(for: schema, configurations: [configuration])

        for product in products {
            container.mainContext.insert(product)
        }
        try container.mainContext.save()

        containerResult = .success(container)
    } catch {
        containerResult = .failure(error)
    }
